import{_ as i,o as e,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Developer Summit Quincy: CephFS Follow-up","description":"","frontmatter":{"title":"Ceph Developer Summit Quincy: CephFS Follow-up","date":"2021-04-28T00:00:00.000Z","updated":"2021-04-29T00:00:00.000Z","tags":["CephFS","Quincy版本","Trello Backlog","开发者会议","Ceph生态系统"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_CephFS_Follow-up.md","filePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_CephFS_Follow-up.md","lastUpdated":1780459816000}'),p={name:"posts/2021/Ceph_Developer_Summit_Quincy_-_CephFS_Follow-up.md"};function u(n,l,r,c,S,a){return e(),o("div",null,[...l[0]||(l[0]=[t("<p>Ceph开发者峰会的Quincy版本跟进会议主要讨论了CephFS项目的上游Trello backlog board，并规划了即将到来的Quincy版本的工作内容。</p><p><strong>会议要点</strong>：</p><ul><li><strong>Trello Backlog</strong>: 会议回顾了Trello backlog中的各项任务，包括多MDS导出冲突、MDS版本检查、碎片处理、MDS内存目标等。</li><li><strong>Quincy版本工作内容</strong>： <ul><li>多MDS导出冲突的PR因MDS相关问题失败，需要先解决MDS问题。</li><li>MDS版本检查将发出健康警告，继续跟踪此问题。</li><li>碎片处理需要基于最新代码进行调整，并进行审查。</li><li>MDS内存目标考虑采用优先级缓存方法。</li><li>客户端Lazy IO支持因实现难度和需求不明确，决定不作为Quincy版本的工作内容。</li><li>Root Squash via MDS Capability已在Pacific版本中实现。</li><li>HSM Support因缺乏下游需求，决定不作为Quincy版本的工作内容。</li><li>Optimized Rsync因CephFS Mirror的存在，决定关闭此优化需求。</li><li>Multi-FS Shared Pools因技术限制和需求变化，决定关闭此需求。</li><li>Snapshots File Level Snapshots因技术挑战和实际需求，决定暂时不作为Quincy版本的工作内容。</li><li>Background Fored Scrub Scheduling计划在Quincy版本中实现。</li><li>FFS Notify Support因在VFS层实现通知支持的难度，决定暂时不作为Quincy版本的工作内容。</li><li>MDS Star因需要大规模重写MDS，决定暂时不作为Quincy版本的工作内容。</li><li>Libs FFS PP因C API与C++ API分离的需求，决定暂时不作为Quincy版本的工作内容。</li><li>Ceph Top MultiFS Support需改进mgr stats模块以支持多文件系统，计划在Quincy版本中实现。</li><li>Recursive Unlink RPC计划在Quincy版本中实现。</li><li>AHA Support计划在Quincy版本中实现。</li><li>SFS Cache等待内核补丁的进展，计划在Quincy版本中实现。</li><li>Client Expose Auth MDS for Fileder讨论了在客户端暴露权威MDS的需求，决定暂时不作为Quincy版本的工作内容。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>继续跟踪和更新Trello board，确保所有工作内容和进度得到准确反映。</li><li>对于标记为Quincy版本的工作内容，需尽快找到负责人并开始实施。</li><li>对于暂时不作为Quincy版本的工作内容，将继续在backlog中跟踪，等待合适的时机再进行处理。</li></ul></li></ul><p><strong>关键词</strong>： CephFS, Quincy版本, Trello Backlog, 开发者会议, Ceph生态系统</p>",4)])])}const h=i(p,[["render",u]]);export{_ as __pageData,h as default};
